{
 "version": "0.102.3",
 "commands": {
  "test": [
   "flutter test --fail-fast --concurrency=12 --file-reporter json:build/guild-test-report.json",
   "scripts/verify_test_coverage.sh build/guild-test-report.json"
  ],
  "lint": [
   "flutter analyze",
   "npx cspell '**' --gitignore --no-progress",
   "npx remark . --quiet --frail"
  ],
  "typecheck": null,
  "build": "flutter build apk",
  "e2e": "flutter test integration_test/app_test.dart",
  "vrt": null
 },
 "visual": {
  "baselines": [
   "test/**/goldens/**"
  ],
  "tests": [],
  "matchers": [],
  "packages": [],
  "run_file": "flutter test <file>",
  "config_files": [
   "**/flutter_test_config.dart",
   "dart_test.yaml",
   "test/helpers/load_font.dart"
  ],
  "runnable": true,
  "env": "macOS arm64 local (lefthook pre-commit 의 전체 flutter test 로 비교); CI ubuntu-latest amd64 는 main 기준 재생성 후 비교",
  "create": "flutter test --update-goldens <file>"
 },
 "engine": {}
}
